-- Corrections du quiz de fin de semaine : vagues_courants.
--
-- Générées par scripts/importer-quiz.mjs. `data` porte la version adulte, 
-- `data.version_enfant` la version enfant du même sujet. Remplace `version_moniteur`
-- (même rôle, jamais exploité par un vrai choix au lancement avant ce jour).

UPDATE game_cards SET related_objective_id = '31', data = '{"question":"Quelle est la différence entre la mer du vent et la houle ?","answers":["Il n''y a aucune différence","La mer du vent est courte et désordonnée (locale) ; la houle est longue et régulière, venue de loin","La houle n''existe qu''en pleine mer","Les vagues sont toujours plus grosses que la houle"],"correctAnswerIndex":1,"explanation":"La houle a voyagé loin de la tempête qui l''a créée et s''est organisée en chemin. On peut avoir de la houle par vent calme sur place.","version_enfant":{"question":"Pourquoi peut-il y avoir de grosses vagues alors qu''il n''y a pas de vent ici ?","answers":["C''est impossible","Parce que la houle vient d''une tempête qui a eu lieu loin d''ici","Parce que la marée les crée","Parce que les courants les fabriquent"],"correctAnswerIndex":1,"explanation":"La houle d''aujourd''hui a été levée par une tempête lointaine, il y a plusieurs jours. Elle voyage sans avoir besoin de vent sur place."}}'::jsonb WHERE id = '352ae64c-cb51-4f6c-b348-45d572174b36';
UPDATE game_cards SET related_objective_id = '104', data = '{"question":"Quels sont les trois facteurs qui déterminent la taille d''une houle ?","answers":["La profondeur, la salinité et la température de l''eau","La vitesse du vent, sa durée, et le fetch (distance d''eau libre)","La lune, le soleil et la pression atmosphérique","Le courant marin, la marée et la pression"],"correctAnswerIndex":1,"explanation":"Plus le vent est fort, souffle longtemps et sur une grande distance (fetch), plus la houle est puissante. Diminuer un seul facteur limite la houle.","version_enfant":{"question":"Qu''est-ce qui fait les grosses vagues ?","answers":["La force du vent, le temps qu''il souffle, et la distance de mer qu''il traverse","Seulement la force du vent","Seulement la profondeur de l''eau","La couleur du ciel"],"correctAnswerIndex":0,"explanation":"Trois choses comptent : la force du vent, depuis combien de temps il souffle, et sur quelle distance de mer. Il faut les trois pour de grosses vagues."}}'::jsonb WHERE id = '31cce895-53e5-4e59-acfb-8b05fc3a8c76';
UPDATE game_cards SET related_objective_id = '32', data = '{"question":"Comment se produit le déferlement des vagues à l''approche du rivage ?","answers":["Uniquement à cause du vent côtier","Quand la profondeur devient insuffisante, la base de la vague ralentit et la crête la dépasse : elle déferle","Les vagues déferlent uniquement à marée haute","Le déferlement est causé par le courant de marée uniquement"],"correctAnswerIndex":1,"explanation":"En eau peu profonde, la base de la vague freine sur le fond tandis que la crête continue d''avancer : elle finit par dépasser la base et s''effondrer.","version_enfant":{"question":"Pourquoi les vagues cassent-elles près de la plage ?","answers":["Parce qu''elles sont trop grosses","Parce que le fond remonte : le bas de la vague freine mais le haut continue","Parce que le vent les pousse","Parce que la marée les fait tomber"],"correctAnswerIndex":1,"explanation":"Quand le fond remonte, le bas de la vague freine mais le haut continue d''avancer : elle bascule et casse."}}'::jsonb WHERE id = 'ba366b25-85c3-47a8-909f-e5a46247a6e2';
UPDATE game_cards SET related_objective_id = '118', data = '{"question":"Quel est le rôle des courants marins dans la distribution des nutriments ?","answers":["Aucun — les nutriments restent toujours au fond","Ils font remonter l''eau froide riche en nutriments vers la surface (upwelling), permettant à la vie de prospérer","Ils appauvrissent l''eau en nutriments","Seuls les courants profonds ont un rôle"],"correctAnswerIndex":1,"explanation":"Certains courants font remonter vers la surface une eau froide chargée en nutriments accumulés en profondeur : le phytoplancton en profite, nourrissant toute la chaîne alimentaire.","version_enfant":{"question":"Pourquoi voit-on parfois beaucoup d''oiseaux au même endroit en mer ?","answers":["Par hasard","Parce que le courant y fait remonter de la nourriture depuis le fond","Parce qu''ils se reposent toujours là","Parce que l''eau y est plus chaude"],"correctAnswerIndex":1,"explanation":"Les courants remontent la nourriture des profondeurs vers la surface. Là où ils le font, la vie abonde — et les oiseaux le savent."}}'::jsonb WHERE id = '187db14a-4d81-4604-a2b1-55e8326adfc3';
UPDATE game_cards SET related_objective_id = '27', data = '{"question":"Comment repère-t-on le sens du courant dans l''eau ?","answers":["En goûtant l''eau, plus salée dans le sens du courant","En observant l''eau autour d''un obstacle fixe : une traînée d''écume se forme du côté vers lequel elle pousse","En regardant la direction des vagues de surface","En plongeant un bâton verticalement"],"correctAnswerIndex":1,"explanation":"L''eau qui s''écoule autour d''un obstacle fixe (bouée, poteau, rocher) forme une traînée d''écume ou de remous du côté où elle pousse.","version_enfant":{"question":"Comment voit-on de quel côté file le courant ?","answers":["En goûtant l''eau","En regardant la traînée d''écume derrière une bouée ou un poteau","En regardant les vagues","En plantant un bâton"],"correctAnswerIndex":1,"explanation":"L''eau qui file autour d''un obstacle laisse une petite moustache d''écume du côté où elle pousse."}}'::jsonb WHERE id = '4c7d9c79-cdf0-4c71-afe8-85f6024d3399';
UPDATE game_cards SET related_objective_id = '24', data = '{"question":"Comment les différents types de courants s''influencent-ils ?","answers":["Les courants de marée et de vent n''interagissent jamais","Courant de marée, de dérive (vent) et courant général se combinent, créant des zones agitées ou calmes","Seul le courant de marée compte près des côtes","Les courants généraux n''existent pas en Manche"],"correctAnswerIndex":1,"explanation":"Un courant de marée opposé à un courant de vent peut créer une mer très hachée. À l''inverse, aller dans le sens du courant peut doubler la vitesse.","version_enfant":{"question":"Qu''est-ce qui fait bouger l''eau de la mer ?","answers":["Uniquement le vent","Trois choses : la marée, le vent, et les grands courants de l''océan","Uniquement la Lune","Rien, l''eau ne bouge pas toute seule"],"correctAnswerIndex":1,"explanation":"Trois choses font bouger l''eau : la Lune (marée), le vent (dérive), et les grands courants de l''océan. Près des côtes, c''est surtout la marée."}}'::jsonb WHERE id = 'b4902487-e0b0-4ce7-aafe-2a95835d948b';
UPDATE game_cards SET related_objective_id = '97', data = '{"question":"Quels signes visuels permettent d''évaluer l''état de la mer depuis le rivage ?","answers":["La couleur des rochers uniquement","Moutons (écume) sur les crêtes, hauteur des vagues, façon dont elles cassent, visibilité à l''horizon","La présence de bateaux de pêche uniquement","La température de l''air"],"correctAnswerIndex":1,"explanation":"Les moutons apparaissent à partir d''un vent soutenu. La façon dont les vagues cassent et la netteté de l''horizon se lisent depuis le rivage avant de s''engager.","version_enfant":{"question":"Sans mettre un pied dans l''eau, qu''est-ce qu''on peut déjà savoir sur la mer ?","answers":["Rien du tout","Si le vent est fort (écume blanche), si les vagues cassent fort, si l''horizon est net","Seulement s''il y a des bateaux","Seulement la température de l''air"],"correctAnswerIndex":1,"explanation":"Depuis le bord on voit déjà l''essentiel : l''écume blanche trahit le vent, un horizon flou annonce le mauvais temps."}}'::jsonb WHERE id = '39e86933-df36-421b-b68b-8cbdbec70695';
UPDATE game_cards SET related_objective_id = '34', data = '{"question":"Que faut-il observer sur les vagues pour anticiper leur dangerosité ?","answers":["Uniquement leur hauteur","Hauteur, forme (creuses ou douces), fréquence, et présence de ressac sur les zones rocheuses","Uniquement leur couleur","La direction du vent uniquement"],"correctAnswerIndex":1,"explanation":"Des vagues creuses et rapprochées sont plus dangereuses que des vagues douces et longues. Observer plusieurs minutes avant de s''engager permet de voir passer les grosses séries.","version_enfant":{"question":"Pour savoir si les vagues sont dangereuses, on regarde quoi ?","answers":["Seulement leur hauteur","Si elles sont hautes ou basses, creuses ou douces, et si elles cassent souvent","Seulement leur couleur","Seulement le vent"],"correctAnswerIndex":1,"explanation":"Une vague longue et douce laisse le temps de réagir. Une vague courte et creuse casse d''un coup — c''est sa forme qui compte, pas que sa hauteur."}}'::jsonb WHERE id = '03e92576-ae29-49bd-b17f-acdb7a64d6f8';
